import { useEffect, useState } from "react";
import axios from "axios";
import { QRCodeCanvas } from "qrcode.react";

function Dashboard() {

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  const [queues, setQueues] = useState([]);
  const [notification, setNotification] = useState("");

  // Fetch Queue List
  const fetchQueues = async () => {

    try {

      const res = await axios.get(
        "http://localhost:5000/api/queue/all"
      );

      setQueues(res.data);

    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    fetchQueues();
  }, []);

  // Book OP Queue
  const addQueue = async () => {

    if (
      !form.patientName ||
      !form.doctor ||
      !form.department ||
      !form.date
    ) {
      alert("Please Fill All Fields");
      return;
    }

    try {

      const res = await axios.post(
        "http://localhost:5000/api/queue/add",
        form
      );

      setNotification(
        `OP Token ${res.data.tokenNumber} Booked Successfully`
      );

      setForm({
        patientName: "",
        doctor: "",
        department: "",
        date: ""
      });

      fetchQueues();

    } catch (err) {
      console.log(err);

      alert("Failed To Book Queue");
    }
  };

  // Update Queue Status
  const updateStatus = async (id, status) => {

    try {

      await axios.put(
        `http://localhost:5000/api/queue/update/${id}`,
        {
          status
        }
      );

      setNotification("Patient Completed");

      fetchQueues();

    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div
      style={{
        padding: "40px",
        backgroundColor: "#f5f7fa",
        minHeight: "100vh"
      }}
    >

      <h1
        style={{
          textAlign: "center",
          marginBottom: "30px",
          color: "#1e3a8a"
        }}
      >
        PulseLine Hospital Queue System
      </h1>

      {/* Notification */}
      {notification && (
        <div
          style={{
            backgroundColor: "#22c55e",
            color: "white",
            padding: "12px",
            borderRadius: "10px",
            marginBottom: "20px",
            textAlign: "center",
            fontWeight: "bold"
          }}
        >
          {notification}
        </div>
      )}

      {/* Booking Form */}
      <div
        style={{
          backgroundColor: "white",
          padding: "25px",
          borderRadius: "15px",
          marginBottom: "30px",
          boxShadow: "0 0 10px rgba(0,0,0,0.1)"
        }}
      >

        <h2>Book OP Appointment</h2>

        <input
          type="text"
          placeholder="Patient Name"
          value={form.patientName}
          onChange={(e) =>
            setForm({
              ...form,
              patientName: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="text"
          placeholder="Doctor Name"
          value={form.doctor}
          onChange={(e) =>
            setForm({
              ...form,
              doctor: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="text"
          placeholder="Department"
          value={form.department}
          onChange={(e) =>
            setForm({
              ...form,
              department: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) =>
            setForm({
              ...form,
              date: e.target.value
            })
          }
          style={inputStyle}
        />

        <button
          onClick={addQueue}
          style={buttonStyle}
        >
          Book OP
        </button>

      </div>

      {/* Queue List */}
      <h2>Patient Queue List</h2>

      {queues.map((q) => (

        <div
          key={q._id}
          style={{
            backgroundColor: "white",
            padding: "20px",
            borderRadius: "15px",
            marginBottom: "20px",
            boxShadow: "0 0 10px rgba(0,0,0,0.1)"
          }}
        >

          <h3 style={{ color: "#2563eb" }}>
            Token: {q.tokenNumber}
          </h3>

          <p>
            <strong>Patient:</strong> {q.patientName}
          </p>

          <p>
            <strong>Doctor:</strong> {q.doctor}
          </p>

          <p>
            <strong>Department:</strong> {q.department}
          </p>

          <p>
            <strong>Date:</strong> {q.date}
          </p>

          <p>
            <strong>Status:</strong> {q.status}
          </p>

          {/* QR Code */}
          <QRCodeCanvas
            value={JSON.stringify({
              token: q.tokenNumber,
              patient: q.patientName,
              doctor: q.doctor,
              department: q.department,
              date: q.date,
              status: q.status
            })}
            size={140}
          />

          <br />
          <br />

          <button
            onClick={() =>
              updateStatus(q._id, "Completed")
            }
            style={{
              backgroundColor: "#dc2626",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "8px",
              cursor: "pointer"
            }}
          >
            Complete
          </button>

        </div>
      ))}

    </div>
  );
}

// Input Style
const inputStyle = {
  width: "100%",
  padding: "12px",
  marginBottom: "15px",
  borderRadius: "8px",
  border: "1px solid #ccc",
  fontSize: "16px"
};


const buttonStyle = {
  backgroundColor: "#2563eb",
  color: "white",
  padding: "12px 20px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontSize: "16px"
};

export default Dashboard;
